-- Gestão Restaurante MVP | MySQL 8 / MariaDB 10.4+
-- No cPanel: crie banco e usuário, selecione o banco no phpMyAdmin e importe este arquivo.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS relatorios_salvos, auditoria, desperdicios, ficha_tecnica_itens, fichas_tecnicas, produtos, fornecedores, categorias_produto, unidades_medida, usuarios;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE usuarios (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, perfil ENUM('admin','gestor','operacional') NOT NULL DEFAULT 'operacional', ativo TINYINT(1) NOT NULL DEFAULT 1, criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE categorias_produto (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(80) NOT NULL UNIQUE, ativo TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE unidades_medida (codigo VARCHAR(12) PRIMARY KEY, nome VARCHAR(40) NOT NULL, ordem INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fornecedores (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, documento VARCHAR(30), telefone VARCHAR(30), contato VARCHAR(100), ativo TINYINT(1) DEFAULT 1, criado_em DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE produtos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, codigo VARCHAR(60), categoria_id INT UNSIGNED, marca VARCHAR(100), unidade_compra VARCHAR(12) NOT NULL, unidade_consumo VARCHAR(12) NOT NULL, fator_conversao DECIMAL(12,4) NOT NULL DEFAULT 1, rendimento_percentual DECIMAL(7,2) NOT NULL DEFAULT 100, estoque_minimo DECIMAL(12,3) DEFAULT 0, preco_atual DECIMAL(12,4) NOT NULL DEFAULT 0, fornecedor_principal_id INT UNSIGNED, ativo TINYINT(1) DEFAULT 1, criado_em DATETIME DEFAULT CURRENT_TIMESTAMP, atualizado_em DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(categoria_id) REFERENCES categorias_produto(id), FOREIGN KEY(fornecedor_principal_id) REFERENCES fornecedores(id), INDEX(nome)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fichas_tecnicas (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, codigo VARCHAR(60), categoria_id INT UNSIGNED, tipo VARCHAR(40) DEFAULT 'prato', rendimento_total DECIMAL(12,3) NOT NULL, unidade_rendimento VARCHAR(12) NOT NULL, porcoes DECIMAL(12,3) NOT NULL DEFAULT 1, tamanho_porcao DECIMAL(12,3) DEFAULT 0, modo_preparo TEXT, status ENUM('rascunho','aprovada','arquivada') DEFAULT 'rascunho', preco_venda DECIMAL(12,2) DEFAULT 0, versao INT DEFAULT 1, criado_em DATETIME DEFAULT CURRENT_TIMESTAMP, atualizado_em DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(categoria_id) REFERENCES categorias_produto(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ficha_tecnica_itens (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ficha_id INT UNSIGNED NOT NULL, produto_id INT UNSIGNED NOT NULL, quantidade_bruta DECIMAL(12,4) NOT NULL, quantidade_liquida DECIMAL(12,4) NOT NULL, fator_correcao DECIMAL(12,4) DEFAULT 1, FOREIGN KEY(ficha_id) REFERENCES fichas_tecnicas(id) ON DELETE CASCADE, FOREIGN KEY(produto_id) REFERENCES produtos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE desperdicios (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, produto_id INT UNSIGNED NOT NULL, quantidade DECIMAL(12,4) NOT NULL, unidade VARCHAR(12) NOT NULL, etapa VARCHAR(40) NOT NULL, motivo VARCHAR(120) NOT NULL, valor_estimado DECIMAL(12,2) DEFAULT 0, data_registro DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, usuario_id INT UNSIGNED NOT NULL, observacoes TEXT, FOREIGN KEY(produto_id) REFERENCES produtos(id), FOREIGN KEY(usuario_id) REFERENCES usuarios(id), INDEX(data_registro)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE auditoria (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, usuario_id INT UNSIGNED, acao VARCHAR(40) NOT NULL, entidade VARCHAR(60) NOT NULL, entidade_id INT UNSIGNED, detalhes JSON, criado_em DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE relatorios_salvos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, titulo VARCHAR(180) NOT NULL, data_inicio DATE NOT NULL, data_fim DATE NOT NULL, dados LONGTEXT NOT NULL, usuario_id INT UNSIGNED NOT NULL, criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(usuario_id) REFERENCES usuarios(id), INDEX(criado_em)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

